/*
 * A042360  Numerators of continued fraction convergents to sqrt(707).
 * https://oeis.org/A042360
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(n) = numerator of the nth convergent to sqrt(707) computed by
 *            the standard continued‑fraction recurrence: p_{-2} = 0, p_{-1} =
 *            1 p_k = a_k * p_{k-1} + p_{k-2} where the partial quotients a_k
 *            of sqrt(707) are generated by the classical algorithm from the
 *            recursive m_{k+1} = d_k * a_k - m_k d_{k+...
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 19, u64 n <= 39, u128 n <= 81,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* constants for √707  */
    const int64_t D      = 707LL;          /* D > 0 */
    const int64_t a0     = 26LL;           /* floor(sqrt(707)) */

    /* continued‑fraction variables (32‑bit are enough for D=707) */
    int64_t m = 0, d = 1, a_k = a0;

    /* convergent recurrence */
    seq_t p_minus2 = 0;   /* p_{-2} */
    seq_t p_minus1 = 1;   /* p_{-1} */

    for (idx_t i = 0; /* n is unsigned */; ++i) {
        /* compute current convergent numerator p_i */
        seq_t p_i = (seq_t)a_k * p_minus1 + p_minus2;

        if (i == n)
            return p_i;

        /* advance continued‑fraction partial quotients */
        int64_t m_next = d * a_k - m;
        int64_t d_next = (D - m_next * m_next) / d;
        int64_t a_next = (a0 + m_next) / d_next;

        m = m_next;
        d = d_next;
        a_k = a_next;

        /* shift previous two numerators */
        p_minus2 = p_minus1;
        p_minus1 = p_i;
    }
}
